SS_MSG(title, EN("Align photographs to a reference splat"), JA("参照スプラットに写真を整列"), ZH_HANS("将照片对齐到参考泼溅"), ZH_HANT("將照片對齊至參考潑濺"), KO("사진을 기준 스플랫에 정렬"), DE("Fotos an einem Referenz-Splat ausrichten"), FR("Aligner les photos sur un splat de référence"), ES("Alinear fotos con un splat de referencia"), PT("Alinhar fotos a um splat de referência"), IT("Allinea foto a uno splat di riferimento"), NL("Foto’s uitlijnen op een referentiesplat"), RU("Совместить фотографии с эталонным сплатом"), TR("Fotoğrafları referans splata hizala"));
